const NOW_MS: u64 = 1_800_000_000_000;
const HOUR_MS: u64 = 3_600_000;
const EXPIRES_MS: u64 = NOW_MS + HOUR_MS;
const EXPIRES_LATE_MS: u64 = NOW_MS + 2 * HOUR_MS;
const DELAY_MS: u64 = HOUR_MS;
/// issuer_key_delay_ms after setup().
const KEY_DELAY_MS: u64 = HOUR_MS / 2;
/// governance_delay_ms after setup(). Fixture tokens stay valid until NOW_MS + 3 h.
const GOV_DELAY_MS: u64 = 2 * HOUR_MS;
const SALT: [u8; 16] = [9; 16];

const USER: &str = "1098765432";
const OWNER_SUB: &str = "owner-111";
const A: &str = "app-a.apps.googleusercontent.com";
const A2: &str = "app-a2.apps.googleusercontent.com";
const B: &str = "app-b.apps.googleusercontent.com";
const C: &str = "app-c.apps.googleusercontent.com";
const D: &str = "app-d.apps.googleusercontent.com";
const E: &str = "app-e.apps.googleusercontent.com";
const CONSOLE: &str = "console.apps.googleusercontent.com";
/// Hana's shared login client.
const SHARED: &str = "hana-shared.apps.googleusercontent.com";

const ME: &str = "hana-signer.testnet";
/// A second deployment, for cross-deployment replay tests.
const OTHER_ME: &str = "hana-signer-other.testnet";
const ADMIN: &str = "admin.testnet";
const RELAYER: &str = "relayer.testnet";
const ALICE: &str = "alice.testnet";
const BOB: &str = "bob.testnet";
const MALLORY: &str = "mallory.testnet";
const CAROL: &str = "carol.testnet";
/// A watchdog that may confirm from NOW_MS (added in setup() while the governance delay was 0).
const WATCHDOG: &str = "watchdog.testnet";
const WATCHDOG2: &str = "watchdog2.testnet";

std::thread_local! {
    /// The contract account (`env::current_account_id()`) for this test's calls. Each test runs on its own thread.
    static CURRENT_ACCOUNT: std::cell::Cell<&'static str> = const { std::cell::Cell::new(ME) };
}

// ---- helpers ----

fn acc(s: &str) -> AccountId {
    s.parse().unwrap()
}

fn vm_context(caller: &str, ms: u64, deposit: NearToken) -> VMContext {
    VMContextBuilder::new()
        .current_account_id(acc(CURRENT_ACCOUNT.with(|a| a.get())))
        .predecessor_account_id(acc(caller))
        .signer_account_id(acc(caller))
        .block_timestamp(ms * 1_000_000)
        .attached_deposit(deposit)
        .account_balance(NearToken::from_near(100))
        .build()
}

fn ctx_with(caller: &str, ms: u64, deposit: NearToken) {
    testing_env!(vm_context(caller, ms, deposit));
}

/// A fresh mocked blockchain (no receipts, no logs) whose storage is `storage`.
fn ctx_with_storage(caller: &str, ms: u64, storage: std::collections::HashMap<Vec<u8>, Vec<u8>>) {
    env::set_blockchain_interface(near_sdk::MockedBlockchain::new(
        vm_context(caller, ms, NearToken::from_near(1)),
        near_sdk::test_vm_config(),
        near_sdk::RuntimeFeesConfig::test(),
        vec![],
        storage,
        Default::default(),
        None,
    ));
}

/// Runs `call` on `c` as the runtime runs one receipt (caller RELAYER, at NOW_MS). A unit test otherwise sees the
/// writes a panicking call made before it panicked; here a panic restores storage, receipts and logs to how they were
/// before the call, as the runtime reverts a failed receipt. Returns the contract as stored afterwards and the panic
/// message, if any.
fn as_receipt(c: HanaSigner, call: impl FnOnce(&mut HanaSigner)) -> (HanaSigner, Option<String>) {
    env::state_write(&c);
    drop(c); // flushes the collections' caches into storage
    let before = near_sdk::mock::with_mocked_blockchain(|b| b.take_storage());
    ctx_with_storage(RELAYER, NOW_MS, before.clone());
    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut c: HanaSigner = env::state_read().expect("contract state");
        call(&mut c);
        env::state_write(&c);
    }));
    let err = outcome.err().map(panic_msg);
    if err.is_some() {
        ctx_with_storage(RELAYER, NOW_MS, before);
    }
    (env::state_read().expect("contract state"), err)
}

/// Attaches 1 NEAR, which payable methods use for storage (excess refunded); non-payable methods ignore it here.
fn ctx(caller: &str, ms: u64) {
    ctx_with(caller, ms, NearToken::from_near(1));
}

fn panic_msg(err: Box<dyn std::any::Any + Send>) -> String {
    err.downcast_ref::<String>().cloned().or_else(|| err.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default()
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("test_fixture.json")).unwrap()
}

fn tok(name: &str) -> String {
    fixture()["tokens"][name].as_str().unwrap_or_else(|| panic!("no fixture token {name}")).to_string()
}

fn fixture_nonce(name: &str) -> String {
    fixture()["nonces"][name].as_str().unwrap().to_string()
}

fn sk(seed: u8) -> SigningKey {
    SigningKey::from_bytes(&[seed; 32])
}

fn pk(seed: u8) -> Vec<u8> {
    sk(seed).verifying_key().to_bytes().to_vec()
}

/// An ed25519 access-key public key.
fn near_pk(seed: u8) -> near_sdk::PublicKey {
    near_sdk::PublicKey::from_parts(near_sdk::CurveType::ED25519, pk(seed)).unwrap()
}

fn near_owner(a: &str) -> Owner {
    Owner::Near { account_id: acc(a) }
}

fn oidc_owner(sub: &str) -> Owner {
    Owner::Oidc { provider: "google".into(), sub: sub.into() }
}

fn google(aud: &str) -> (String, String) {
    ("google".into(), aud.into())
}

fn add(aud: &str) -> Change {
    Change::AddClient { provider: "google".into(), aud: aud.into() }
}

fn oidc(token: &str) -> OwnerAuth {
    OwnerAuth::Oidc { jwt: tok(token) }
}

/// A fresh contract with the fixture issuer key (active), a console audience (in force), and two admin-registered
/// scopes: s1 = owners [alice, Oidc owner-111], clients [A, A2]; s2 = owners [bob], clients [B]. Built with zero
/// delays (so the key and the audience are in force at once), then the delays are raised (increases apply at once):
/// change_delay_ms = DELAY_MS, issuer_key_delay_ms = KEY_DELAY_MS, governance_delay_ms = GOV_DELAY_MS. WATCHDOG was
/// added while the governance delay was 0, so it may confirm from NOW_MS.
fn setup() -> HanaSigner {
    // Empty storage, so a test may set up several contracts in turn.
    ctx_with_storage(ADMIN, NOW_MS, Default::default());
    let f = fixture();
    let mut c = HanaSigner::new(acc(ADMIN), acc("v1.signer-prod.testnet"), 2, 0, 0, 0, vec![], vec![]);
    c.set_issuer("google".into(), vec!["https://accounts.google.com".into(), "accounts.google.com".into()]);
    let id = c.set_issuer_key("google".into(), "test-kid".into(), f["n"].as_str().unwrap().into(), f["e"].as_str().unwrap().into(), None);
    c.execute_issuer_key_change(id);
    c.set_console_audiences(vec![google(CONSOLE)]);
    c.set_sponsors(vec![acc(RELAYER)]);
    c.add_watchdog(acc(WATCHDOG));
    c.set_change_delay_ms(DELAY_MS);
    c.set_issuer_key_delay_ms(KEY_DELAY_MS);
    c.set_governance_delay_ms(GOV_DELAY_MS);
    assert_eq!(c.admin_register_scope(vec![near_owner(ALICE), oidc_owner(OWNER_SUB)], vec![google(A), google(A2)], None, false), "s1");
    assert_eq!(c.admin_register_scope(vec![near_owner(BOB)], vec![google(B)], None, false), "s2");
    c
}

/// Proposes `kid` = (n, e) for `provider` as the owner and confirms it as WATCHDOG, at NOW_MS: the key is active.
fn post_key(c: &mut HanaSigner, provider: &str, kid: &str, n: &str, e: &str) {
    ctx(ADMIN, NOW_MS);
    let id = c.set_issuer_key(provider.into(), kid.into(), n.into(), e.into(), None);
    ctx(WATCHDOG, NOW_MS);
    c.confirm_issuer_key_change(id);
}

/// The fixture's google key (n, e).
fn fixture_key() -> (String, String) {
    let f = fixture();
    (f["n"].as_str().unwrap().to_string(), f["e"].as_str().unwrap().to_string())
}

/// Opens a session with `token` in `scope` (expiry EXPIRES_MS, salt SALT, max_uses 3: what the fixture nonces commit to).
fn open(c: &mut HanaSigner, token: &str, scope: &str, seed: u8, key_index: u32) -> Session {
    c.create_session(tok(token), scope.into(), pk(seed), EXPIRES_MS, SALT.to_vec(), key_index, 3, create_sig(&pk(seed)))
}

fn session_sig(seed: u8, counter: u64, payload: &[u8]) -> Vec<u8> {
    sk(seed).sign(&session_message_bytes(counter, payload)).to_bytes().to_vec()
}

/// The session key's proof of possession for a bare `create_session` (session_message(0, "hana-id-create-v1"), D137),
/// for the test key whose public key is `key` (seeds 0..=255); 64 zero bytes for any other key.
fn create_sig(key: &[u8]) -> Vec<u8> {
    (0..=255u8)
        .find(|&s| pk(s) == key)
        .map(|s| session_sig(s, 0, crate::sessions::CREATE_PAYLOAD))
        .unwrap_or_else(|| vec![0; 64])
}

fn ckd_sig(seed: u8, counter: u64, pk1: &str, pk2: &str) -> Vec<u8> {
    session_sig(seed, counter, &ckd_request_bytes(pk1, pk2))
}

fn derive(c: &mut HanaSigner, seed: u8, counter: u64) {
    let _ = c.derive_key(pk(seed), counter, ckd_sig(seed, counter, "bls12381g1:A", "bls12381g2:B"), "bls12381g1:A".into(), "bls12381g2:B".into());
}

fn events() -> Vec<Value> {
    get_logs().iter().filter_map(|l| l.strip_prefix("EVENT_JSON:")).map(|j| serde_json::from_str(j).unwrap()).collect()
}

fn transfers() -> Vec<(String, u128)> {
    get_created_receipts()
        .into_iter()
        .flat_map(|r| {
            let to = r.receiver_id.to_string();
            r.actions.into_iter().filter_map(move |a| match a {
                MockAction::Transfer { deposit, .. } => Some((to.clone(), deposit.as_yoctonear())),
                _ => None,
            })
        })
        .collect()
}

// ---- byte layouts: Rust and the independent JS implementation agree ----

fn hex(bytes: &[u8]) -> String {
    bytes.iter().fold(String::new(), |mut out, b| {
        use std::fmt::Write;
        let _ = write!(out, "{b:02x}");
        out
    })
}

fn borsh_cat(parts: &[Vec<u8>]) -> Vec<u8> {
    parts.concat()
}

fn bs<T: near_sdk::borsh::BorshSerialize + ?Sized>(value: &T) -> Vec<u8> {
    near_sdk::borsh::to_vec(value).unwrap()
}

/// Compares Rust's bytes (and nonce) with the worked example the JS wrote under `layouts.<name>`.
fn check_layout(name: &str, rust_bytes: &[u8], rust_nonce: Option<String>) {
    let f = fixture();
    let ex = &f["layouts"][name];
    assert!(ex.is_object(), "no layout example {name}");
    let parts: Vec<String> = ex["parts"].as_array().unwrap().iter().map(|p| format!("  {}: {}", p[0].as_str().unwrap(), p[1].as_str().unwrap())).collect();
    assert_eq!(hex(rust_bytes), ex["preimage_hex"].as_str().unwrap(), "{name}: Rust bytes differ from the JS implementation; JS parts:\n{}", parts.join("\n"));
    match rust_nonce {
        Some(nonce) => assert_eq!(nonce, ex["nonce"].as_str().unwrap(), "{name}: nonce"),
        None => assert!(ex.get("nonce").is_none(), "{name}: unexpected nonce"),
    }
}

fn commitment<'a>(signer: &'a str, scope_id: &'a str, key: &'a [u8], expires_at_ms: u64, key_index: u32) -> SessionCommitment<'a> {
    SessionCommitment { signer, scope_id, session_public_key: key, expires_at_ms, key_index, max_uses: 3, salt: &SALT }
}

#[test]
fn layouts_match_the_js_implementation() {
    ctx(ADMIN, NOW_MS);
    let f = fixture();
    assert_eq!(f["signer"], ME);
    assert_eq!(f["other_signer"], OTHER_ME);
    assert_eq!(hex(&pk(7)), f["session_pk7_hex"].as_str().unwrap());
    assert_eq!(hex(&pk(8)), f["session_pk8_hex"].as_str().unwrap());

    let (pk7, pk8) = (pk(7), pk(8));
    let session = commitment(ME, "s1", &pk7, EXPIRES_MS, 0);
    check_layout("session_nonce", &session_nonce_preimage(&session), Some(session_nonce(&session)));
    let reg_c = [google(C)];
    check_layout("register_proof", &register_preimage(ME, &reg_owners(), &reg_c, false), Some(register_nonce(ME, &reg_owners(), &reg_c, false)));
    check_layout("client_proof", &client_proof_preimage(ME, "s1", 0), Some(client_proof_nonce(ME, "s1", 0)));
    let remove_args = borsh_cat(&[bs("s1"), bs("google"), bs(A2)]);
    check_layout("owner_action_remove_client", &owner_action_preimage(ME, "s1", "remove_client", &remove_args, 0), Some(owner_action_nonce(ME, "s1", "remove_client", &remove_args, 0)));
    let allow_args = borsh_cat(&[bs("s1"), bs(&Change::SetAllowShared { allow: true }), bs(&None::<String>)]);
    check_layout("owner_action_allow_shared", &owner_action_preimage(ME, "s1", "propose_change", &allow_args, 0), Some(owner_action_nonce(ME, "s1", "propose_change", &allow_args, 0)));
    let disable_args = bs("s1");
    check_layout("owner_action_disable_shared", &owner_action_preimage(ME, "s1", "disable_shared_login", &disable_args, 1), Some(owner_action_nonce(ME, "s1", "disable_shared_login", &disable_args, 1)));
    let ckd = &f["layouts"]["ckd_payload"];
    let ckd_payload = ckd_request_bytes(ckd["pk1"].as_str().unwrap(), ckd["pk2"].as_str().unwrap());
    check_layout("ckd_payload", &ckd_payload, None);
    check_layout("session_message_ckd", &session_message_bytes(1, &ckd_payload), None);
    check_layout("session_message_revoke", &session_message_bytes(2, b"revoke"), None);
    // The view returns exactly these bytes.
    let c = setup();
    assert_eq!(c.session_message(1, ckd_payload.clone()), session_message_bytes(1, &ckd_payload));

    // The nonces the fixture tokens carry.
    let cases: Vec<(&str, String)> = vec![
        ("session_s1_pk8_k1", session_nonce(&commitment(ME, "s1", &pk8, EXPIRES_MS, 1))),
        ("session_s1_pk7_late_k0", session_nonce(&commitment(ME, "s1", &pk7, EXPIRES_LATE_MS, 0))),
        ("session_s1_pk7_other_signer", session_nonce(&commitment(OTHER_ME, "s1", &pk7, EXPIRES_MS, 0))),
        ("session_s3_pk7_k0", session_nonce(&commitment(ME, "s3", &pk7, EXPIRES_MS, 0))),
        ("register_reg_cd", register_nonce(ME, &reg_owners(), &[google(C), google(D)], false)),
        ("register_reg_c_shared", register_nonce(ME, &reg_owners(), &[google(C)], true)),
        ("register_mallory_a2", register_nonce(ME, &[near_owner(MALLORY)], &[google(A2)], false)),
        ("client_s2_0", client_proof_nonce(ME, "s2", 0)),
        ("owner_cancel_s1_0_at_1", owner_action_nonce(ME, "s1", "cancel_change", &borsh_cat(&[bs("s1"), bs(&0u64)]), 1)),
        ("owner_cancel_method_remove_args_s1_0", owner_action_nonce(ME, "s1", "cancel_change", &remove_args, 0)),
        ("owner_disable_shared_s1_1", owner_action_nonce(ME, "s1", "disable_shared_login", &disable_args, 1)),
        (
            "owner_propose_e_s1_0",
            owner_action_nonce(ME, "s1", "propose_change", &borsh_cat(&[bs("s1"), bs(&add(E)), bs(&Some(tok("cp_e_s1_0")))]), 0),
        ),
    ];
    for (name, rust) in cases {
        assert_eq!(rust, fixture_nonce(name), "{name}");
    }
}

#[test]
#[should_panic(expected = "Invalid session signature")]
fn the_old_session_domain_is_rejected() {
    let mut c = setup();
    open(&mut c, "session_a", "s1", 7, 0);
    let payload = ckd_request_bytes("bls12381g1:A", "bls12381g2:B");
    let mut old = b"hana-embed-session-v1:".to_vec();
    old.extend_from_slice(&1u64.to_le_bytes());
    old.extend_from_slice(&near_sdk::env::sha256(&payload));
    let sig = sk(7).sign(&old).to_bytes().to_vec();
    let _ = c.derive_key(pk(7), 1, sig, "bls12381g1:A".into(), "bls12381g2:B".into());
}

