#[test]
fn session_argument_bounds() {
    let mut c = setup();
    let cases: Vec<(Vec<u8>, u64, Vec<u8>, u32, &str)> = vec![
        (vec![1; 31], EXPIRES_MS, SALT.to_vec(), 3, "32-byte"),
        (pk(7), EXPIRES_MS, vec![9; 15], 3, "Salt must be 16-64 bytes"),
        (pk(7), EXPIRES_MS, vec![9; 65], 3, "Salt must be 16-64 bytes"),
        (pk(7), NOW_MS, SALT.to_vec(), 3, "within 24 hours"),
        (pk(7), NOW_MS + 24 * HOUR_MS + 1, SALT.to_vec(), 3, "within 24 hours"),
        (pk(7), EXPIRES_MS, SALT.to_vec(), 0, "max_uses must be 1-500"),
        (pk(7), EXPIRES_MS, SALT.to_vec(), 501, "max_uses must be 1-500"),
    ];
    for (key, expires, salt, max_uses, expected) in cases {
        let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            c.create_session(tok("session_a"), "s1".into(), key.clone(), expires, salt.clone(), 0, max_uses, create_sig(&key.clone()));
        }))
        .expect_err(expected);
        let msg = panic_msg(err);
        assert!(msg.contains(expected), "{msg} should contain {expected}");
    }
}

