#[test]
fn shortening_the_timelock_waits_for_the_old_delay() {
    let mut c = setup();
    c.set_change_delay_ms(0);
    let cfg = c.get_config();
    assert_eq!(cfg.change_delay_ms, DELAY_MS);
    assert_eq!(cfg.pending_change_delay, Some(DelayChange { change_delay_ms: 0, effective_at_ms: NOW_MS + DELAY_MS }));
    // A proposal now still gets the old delay.
    ctx(BOB, NOW_MS);
    let id = c.propose_change("s2".into(), OwnerAuth::Near, Change::SetOwners { owners: vec![near_owner(ALICE)] }, None);
    assert_eq!(c.get_scope("s2".into()).unwrap().pending[0].unlock_at_ms, NOW_MS + DELAY_MS);
    // Once the old delay has passed, the shorter one applies.
    ctx(BOB, NOW_MS + DELAY_MS);
    assert_eq!(c.get_config().change_delay_ms, 0);
    assert_eq!(c.get_config().pending_change_delay, None);
    c.cancel_change("s2".into(), OwnerAuth::Near, id);
    let id = c.propose_change("s2".into(), OwnerAuth::Near, Change::SetOwners { owners: vec![near_owner(ALICE)] }, None);
    c.execute_change("s2".into(), id);
    // Increases apply at once.
    ctx(ADMIN, NOW_MS + DELAY_MS);
    c.set_change_delay_ms(2 * DELAY_MS);
    assert_eq!(c.get_config().change_delay_ms, 2 * DELAY_MS);
}

