    let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| c.execute_change("s1".into(), 1))).unwrap_err();
    assert!(panic_msg(err).contains("A scope has at most 10 clients"));
    let s1 = c.get_scope("s1".into()).unwrap();
